      output = entry.parent;
      continue;
    }

    output.push({ type: "value", path: tag, escaped: true, position });
  }

  const unclosed = stack.at(-1);
  if (unclosed) {
    throw syntaxError(`Unclosed '${unclosed.block.type}' block`, unclosed.block.position);
  }

  return root;
